#ifndef MEP_GAP_LSP_H
#define MEP_GAP_LSP_H

// The analysis half of mep's own GAP language server (the wire half is
// gap_lsp_server.cpp, the `mep-gap-lsp` binary; the `gap_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (gap_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <set>
#include <string>
#include <string_view>
#include <vector>

struct GapLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class GapLspDocument;

struct GapLspOptions {
    // Names the rest of the package (or the file's directory) binds at its top level, from
    // GapLspTopLevelNames over those files: GAP has read them before this one, so they count as bound.
    std::shared_ptr<const std::set<std::string>> context;
    // The package has a compiled kernel extension (src/*.c): it binds names no GAP file shows, so
    // unbound globals are not reported at all.
    bool opaque = false;
};

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const GapLspDocument> GapLspAnalyze(const std::vector<std::string> &lines);
std::shared_ptr<const GapLspDocument> GapLspAnalyze(const std::vector<std::string> &lines, const GapLspOptions &opts);

/** @brief The globals a file binds at its top level (`x := ...`, `for x in`, DeclareAttribute("X") with HasX
 *  and SetX, BindGlobal("X", ...), ...), sorted and unique. A token scan: works on files that do not parse. */
std::vector<std::string> GapLspTopLevelNames(std::string_view text);

// --- Diagnostics ------------------------------------------------------------------

enum class GapLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct GapLspDiagnostic {
    GapLspRange range;
    GapLspSeverity severity = GapLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<GapLspDiagnostic> GapLspDiagnostics(const GapLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string GapLspFormatDiagnostic(const std::string &path, const GapLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool GapLspDiagnosticFails(const GapLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class GapLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct GapLspCompletionItem {
    std::string label;
    std::string insert_text;
    GapLspKind kind = GapLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<GapLspCompletionItem> GapLspCompletions(const GapLspDocument &doc, int line, int col);

struct GapLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    GapLspRange range;
};

GapLspHoverInfo GapLspHover(const GapLspDocument &doc, int line, int col);

struct GapLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

GapLspSignatureHelp GapLspSignatureAt(const GapLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct GapLspLocation {
    GapLspRange range;
};

std::vector<GapLspLocation> GapLspDefinition(const GapLspDocument &doc, int line, int col);

struct GapLspReference {
    GapLspRange range;
    bool is_definition = false;
};

std::vector<GapLspReference> GapLspReferences(const GapLspDocument &doc, int line, int col);

struct GapLspTextEdit {
    GapLspRange range;
    std::string new_text;
};

struct GapLspRenameTarget {
    bool found = false;
    GapLspRange range;
    std::string placeholder;
};

GapLspRenameTarget GapLspPrepareRename(const GapLspDocument &doc, int line, int col);
std::vector<GapLspTextEdit> GapLspRename(const GapLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class GapLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct GapLspSymbol {
    std::string name;
    std::string detail;
    GapLspSymbolKind kind = GapLspSymbolKind::Variable;
    GapLspRange range;
    GapLspRange sel_range;
    int parent = -1;
};

std::vector<GapLspSymbol> GapLspSymbols(const GapLspDocument &doc);

struct GapLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<GapLspFold> GapLspFolds(const GapLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<GapLspTextEdit> GapLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_GAP_LSP_H
